import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.Cxtv3Pj-.js";const g=JSON.parse('{"title":"Updating Your Project","description":"","frontmatter":{},"headers":[],"relativePath":"guide/updating-your-project.md","filePath":"guide/updating-your-project.md","lastUpdated":1785720919000}'),n={name:"guide/updating-your-project.md"};function o(r,e,d,l,h,p){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="updating-your-project" tabindex="-1">Updating Your Project <a class="header-anchor" href="#updating-your-project" aria-label="Permalink to &quot;Updating Your Project&quot;">​</a></h1><p>This page shows you how to update your project <em>after</em> you have put it into production for selling license keys.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you have not put your project into production yet, then you can safely skip this page. If you just want to change some <a href="/reference/config-properties">configuration properties</a>, then you can simply <a href="./getting-started#generating-a-project">regenerate your project</a>.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>In the top-level directory of your generated project, the file <code>pom.xml</code> contains an XML element named <code>properties</code>:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [...]&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">properties</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        [...]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">properties</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>This element gets populated when you <a href="./getting-started#generating-a-project">generate your project</a>. Its contents are a list of XML elements of the form <code>&lt;name&gt;value&lt;/name&gt;</code>. Each element defines a property <code>name</code> and <code>value</code>. These properties get used for code generation, e.g. there is a property named <code>subject</code> whose value defines the name of your software product - see below.</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Changing the property values in the file <code>pom.xml</code> may break compatibility with existing license keys! If you have not already done so, then please <a href="./setting-up-a-vcs">set-up a VCS</a> for your project or otherwise make sure to have some backup before proceeding.</p></div><h2 id="limiting-license-key-validity" tabindex="-1">Limiting License Key Validity <a class="header-anchor" href="#limiting-license-key-validity" aria-label="Permalink to &quot;Limiting License Key Validity&quot;">​</a></h2><p>Let’s assume you want to limit the validity of the license keys for your software product to a particular version number range, e.g. the same major version number. Then you should include this version number range, e.g. the major version number 1, in the value of the property named <code>subject</code>:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">subject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Product 1&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">subject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Later, when you want to publish a new major version number release, e.g. major version number 2, then all you need to do in order to invalidate all previously generated license keys is to update the property value accordingly:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">subject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Product 2&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">subject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>It does not matter how you format the version number range in the licensing subject because the validation function simply compares the complete string. So if you like, you could also set the property value to <code>Product 1.x</code> or <code>Product 2.x</code> instead of <code>Product 1</code> or <code>Product 2</code>, respectively. If TrueLicense finds an old license key installed then a <code>global.namespace.truelicense.api.LicenseValidationException</code><a href="./using-the-api#verifying-the-license-key">gets thrown by the API</a>.</p><h2 id="adding-an-edition" tabindex="-1">Adding An Edition <a class="header-anchor" href="#adding-an-edition" aria-label="Permalink to &quot;Adding An Edition&quot;">​</a></h2><h3 id="adding-the-name" tabindex="-1">Adding The Name <a class="header-anchor" href="#adding-the-name" aria-label="Permalink to &quot;Adding The Name&quot;">​</a></h3><p>Let’s assume you want to add another edition to your software product so that you can upsell a different type of license key for some new features. The value of the property named <code>editions</code> defines a comma separated list of edition names, ordered from feature superset to subset. Each name must be a valid Java identifier and should be camelCased with the initial character being lowercase.</p><p>The name <code>ftp</code> is reserved for an auto-generated free trial period. If you didn’t define a value for this property when generating your project, then the default value is <code>standard</code>:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">editions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;standard&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">editions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>You can simply add the name of the new edition to this list (mind the sorting order from feature superset to subset).</p><p>For example, if you want to sell a higher-priced Enterprise Edition as a superset of the existing Standard Edition, then you need to insert the name of the enterprise edition <em>before</em> the name of the standard edition:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">editions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;enterprise standard&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">editions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>On the other hand, if you want to sell a lower-priced Lite Edition as a subset of the existing Standard Edition, then you need to append the name of the lite edition <em>after</em> the name of the standard edition:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">editions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;standard lite&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">editions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h3 id="adding-the-keystore-password" tabindex="-1">Adding The Keystore Password <a class="header-anchor" href="#adding-the-keystore-password" aria-label="Permalink to &quot;Adding The Keystore Password&quot;">​</a></h3><p>For each edition, there needs to be a password for accessing the individual private key for signing the license keys. If you don’t configure this password, then it defaults to the password for verifying the integrity of the private key store, which defaults to the password set when generating your project. You don’t need to change this password at all, but if you want to, then you can do so by adding a property named <code>\${edition}KeyEntryPassword</code>, where you need to replace <code>\${edition}</code> with the name of the new edition. For example, you can add a password for an edition named <code>enterprise</code> like this:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">enterpriseKeyEntryPassword</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;[...]&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">enterpriseKeyEntryPassword</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>For accessing the entry in the keystore its name needs to be configured, too. This could simply be the name of the edition, like so:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">enterpriseKeyEntryAlias</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;enterprise&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">enterpriseKeyEntryAlias</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h3 id="adding-the-encryption-password" tabindex="-1">Adding The Encryption Password <a class="header-anchor" href="#adding-the-encryption-password" aria-label="Permalink to &quot;Adding The Encryption Password&quot;">​</a></h3><p>For each edition, there needs to be a password for encrypting and decrypting the license keys. If you don’t configure this password, then it defaults to the password set when generating your project. Again, you don’t need to change this password, but if you want to, then you can do so by adding a property named <code>\${edition}PbePassword</code>, where you need to replace <code>\${edition}</code> with the name of the new edition again. For example, you can add a password for an edition named <code>enterprise</code> like this:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">enterprisePbePassword</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;[...]&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">enterprisePbePassword</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h3 id="amending-the-keystores" tabindex="-1">Amending The Keystores <a class="header-anchor" href="#amending-the-keystores" aria-label="Permalink to &quot;Amending The Keystores&quot;">​</a></h3><p>Next, the private and public key stores need to get updated so that they contain a new entry for the new edition. This is done automatically when you are building your project for the very first time. However, when another edition gets added later, this needs to be done manually. You can do it like this:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mvnw</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./mvnw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate-resources</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -Pgenerate-private-key-store</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -Pgenerate-public-key-store</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -Deditions=\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">edition</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span></span></code></pre></div><p>… where you need to replace <code>\${edition}</code> with the name of the new feature set. For example, you can update the keystores for an edition named <code>enterprise</code> like this:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mvnw</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./mvnw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate-resources</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -Pgenerate-private-key-store</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -Pgenerate-public-key-store</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -Deditions=enterprise</span></span></code></pre></div><h2 id="upgrading-your-project" tabindex="-1">Upgrading Your Project <a class="header-anchor" href="#upgrading-your-project" aria-label="Permalink to &quot;Upgrading Your Project&quot;">​</a></h2><p>Let’s assume you want to upgrade your project to benefit from the latest improvements in TrueLicense. In this case, you need to generate a new project and customize it so that it’s fully compatible with existing license keys, i.e. it must be possible to share the same license keys between the old and the new project.</p><h3 id="generating-your-new-project" tabindex="-1">Generating Your New Project <a class="header-anchor" href="#generating-your-new-project" aria-label="Permalink to &quot;Generating Your New Project&quot;">​</a></h3><p>First you need to <a href="./getting-started#generating-a-project">generate a new project</a> and set the values of the properties as explained below.</p><h4 id="upgrading-from-before-truelicense-maven-archetype-2-4" tabindex="-1">Upgrading From Before TrueLicense Maven Archetype 2.4 <a class="header-anchor" href="#upgrading-from-before-truelicense-maven-archetype-2-4" aria-label="Permalink to &quot;Upgrading From Before TrueLicense Maven Archetype 2.4&quot;">​</a></h4><p>If the old project was generated using the TrueLicense Maven Archetype before version 2.4, then you need to set the values of the following properties as follows:</p><dl><dt><code>password</code></dt><dd><p>Enter the value produced by the obfuscated string field <code>PBE_PASSWORD</code> in the class <code>**.keymgr.LicensingSchema$Lazy</code>.</p></dd><dt><code>freeTrialPeriod</code></dt><dd><p>Enter the value of the field <code>FTP_DAYS</code> in the same class.</p></dd><dt><code>ftpKeyStoreFile</code></dt><dd><p>Enter <code>ftp.ks</code>.</p></dd><dt><code>ftpSecretMarkerClass</code></dt><dd><p>Enter the parameter value of the last call to the method <code>.storeInUserNode([...])</code> in the same class, but without the <code>.class</code> suffix, e.g. <code>sun.security.provider.Sun</code>.</p></dd><dt><code>licenseKeyFormat</code></dt><dd><p>Search for the expression matching the pattern <code>new *ManagementContext(SUBJECT)</code> in the same class and select the value as follows:</p><ul><li>For <code>new V1LicenseManagementContext(SUBJECT)</code>, enter <code>V1</code>.</li><li>For <code>new V2XmlLicenseManagementContext(SUBJECT)</code>, enter <code>V2/XML</code>.</li><li>For <code>new V2JsonLicenseManagementContext(SUBJECT)</code>, enter <code>V2/JSON</code> (default).</li></ul></dd><dt><code>subject</code></dt><dd><p>Enter the value of the field <code>SUBJECT</code> in the same class.</p></dd><dt><code>package</code></dt><dd><p>Enter the part of the package name before the <code>keymgr</code> element in the same class.</p></dd><dt><code>preferencesType</code></dt><dd><p>Search for the expression matching the pattern <code>storeIn*Node(LicensingSchema.class)</code> and select the value as follows:</p><ul><li>For <code>storeInSystemNode(LicensingSchema.class)</code>, enter <code>system</code>.</li><li>For <code>storeInUserNode(LicensingSchema.class)</code>, enter <code>user</code>.</li></ul></dd></dl><h4 id="upgrading-from-truelicense-maven-archetype-2-4-or-later" tabindex="-1">Upgrading From TrueLicense Maven Archetype 2.4 Or Later <a class="header-anchor" href="#upgrading-from-truelicense-maven-archetype-2-4-or-later" aria-label="Permalink to &quot;Upgrading From TrueLicense Maven Archetype 2.4 Or Later&quot;">​</a></h4><p>If the old project was generated using the TrueLicense Maven Archetype version 2.4 or later, then you need to ensure that the values of the following properties are equal:</p><ul><li><code>editions</code></li><li><code>freeTrialPeriod</code></li><li><code>ftpKeyStoreFile</code></li><li><code>ftpSecretMarkerClass</code></li><li><code>keyStoreType</code></li><li><code>licenseKeyFormat</code></li><li><code>password</code></li><li><code>pbeAlgorithm</code></li><li><code>preferencesType</code></li><li><code>privateKeyStoreFile</code></li><li><code>publicKeyStoreFile</code></li><li><code>subject</code></li></ul><h3 id="copying-keystores" tabindex="-1">Copying Keystores <a class="header-anchor" href="#copying-keystores" aria-label="Permalink to &quot;Copying Keystores&quot;">​</a></h3><p>Copy the following files from the old project to the new project:</p><ul><li><code>keygen/src/main/resources/\${privateKeyStoreFile}</code></li><li><code>keymgr/src/main/resources/\${ftpKeyStoreFile}</code></li><li><code>keymgr/src/main/resources/\${publicKeyStoreFile}</code></li></ul><h3 id="customizing-properties" tabindex="-1">Customizing Properties <a class="header-anchor" href="#customizing-properties" aria-label="Permalink to &quot;Customizing Properties&quot;">​</a></h3><p>The file <code>pom.xml</code> contains a set of properties with the following name patterns:</p><ul><li><code>*Alias</code></li><li><code>*Password</code></li><li><code>*Type</code></li></ul><p>… where <code>*</code> matches any prefix. Please check the comments for each of these properties in the file and edit their values to match the configuration of the old project. If the old project was generated using the TrueLicense Maven Archetype before version 2.4, then its generally necessary to change the value of the properties named <code>*Alias</code> to <code>mykey</code>, which was the default name for a private key entry or a trusted certificate entry generated by the Java keytool.</p><h3 id="building-your-project" tabindex="-1">Building Your project <a class="header-anchor" href="#building-your-project" aria-label="Permalink to &quot;Building Your project&quot;">​</a></h3><p>You are now set for <a href="./building-your-project">building your project</a> again.</p>`,56)])])}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
